const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');const KEY='nerdy-pip-v1';let state=fresh();let syncKind='saved',syncMessage='Saved to your account';
let disposeAssistant=()=>{},questionClock=null,coachController=null;
let page='adventure',lesson=null,world=0,storeWarning=false;const worldNames=['Little Meadow','Canopy Grove','Wonder Lagoon','Starlight Summit'];
const icons={adventure:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15m6-12v15"/>',skills:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',collection:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M2 7h20M12 7v14M12 7C5 7 5 1 8 2c3 0 4 5 4 5s1-5 4-5c3-1 3 5-4 5"/>',parent:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',gear:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.adventure}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){if(!currentUser())return;state.theme=document.documentElement.dataset.theme==='dark'?'dark':'light';state.world=world;progressStore.schedule(state);}
function updateSync(kind,message){syncKind=kind;syncMessage=message;document.querySelectorAll('.cloud-status').forEach(el=>{el.dataset.status=kind;el.hidden=kind!=='error';el.title=message;el.textContent='Progress kept here · Reconnect';});}
function syncStrip(){return '<div class="sync-strip"><button class="cloud-status" data-action="account" data-status="'+syncKind+'" '+(syncKind!=='error'?'hidden':'')+' title="'+esc(syncMessage)+'">Progress kept here · Reconnect</button></div>';}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function legacyProgress(){try{if(localStorage.getItem('nerdy-legacy-imported'))return null;const old=JSON.parse(localStorage.getItem(KEY));return old?.attempts?.length||old?.sessions?.length?normalize(old):null;}catch{return null;}}
async function accountDialog(){
 modal.className='';const user=currentUser();if(!user)return;const legacy=legacyProgress();
 modal.innerHTML='<h2>Your account</h2><p class="account-email">'+esc(user.email)+'</p><p class="account-note" id="account-sync">'+esc(syncMessage)+'</p><div class="account-actions"><button class="secondary" id="retry-sync">Save now</button><button class="secondary" id="account-logout">Log out</button></div>'+(legacy?'<div class="legacy-import"><strong>Your earlier device progress</strong><p class="account-note">'+legacy.sessions.length+' adventures are still on this browser. Import them into this account only if they belong to you.</p><button class="text-button" id="import-progress">Import my earlier progress</button></div>':'')+'<h3 style="margin-top:24px">Learning journal</h3><ul class="journal-list"><li><span>Current progress</span><button class="text-button" id="current-journal">Download</button></li></ul><p class="account-note">Your download is also saved privately to this account.</p><h3>Saved copies</h3><ul class="journal-list" id="journals"><li>Loading…</li></ul><p id="account-error" class="account-note" role="status"></p><div class="dialog-actions"><button class="primary" id="account-close">Done</button></div>';modal.showModal();
 $('#account-close').onclick=()=>modal.close();$('#retry-sync').onclick=async()=>{await progressStore.flush();$('#account-sync').textContent=syncMessage;};
 if(progressStore.error?.code==='RESET_CONFLICT'){const b=document.createElement('button');b.className='secondary';b.textContent='Download unsaved copy and load saved world';b.onclick=async()=>{b.disabled=true;try{downloadBlob(new Blob([JSON.stringify(progressStore.pending,null,2)],{type:'application/json'}),'nerdy-unsaved-progress.json');state=await progressStore.loadSaved();lesson=null;world=state.world||0;setTheme(state.theme);modal.close();render();}catch(e){$('#account-error').textContent=e.message;b.disabled=false;}};$('#account-sync').after(b);}
 $('#account-logout').onclick=async()=>{const button=$('#account-logout');button.disabled=true;try{await logOut();modal.close()}catch(e){$('#account-error').textContent=e.message;button.disabled=false;}};
 if(legacy)$('#import-progress').onclick=async()=>{const b=$('#import-progress');b.disabled=true;try{legacy.generation=state.generation||'initial';const base=fresh();base.generation=legacy.generation;state=mergeProgress(state,legacy,base);save();if(!await progressStore.flush())throw Error(syncMessage);localStorage.setItem('nerdy-legacy-imported',user.id);modal.close();render();toast('Your earlier discoveries are saved in your account.')}catch(e){$('#account-error').textContent=e.message;b.disabled=false;}};
 async function refreshJournals(){try{const files=await listJournals();if(!$('#journals'))return;$('#journals').innerHTML=files.length?files.map(f=>'<li><span>'+esc(new Date(f.created_at).toLocaleString())+'</span><button class="text-button" data-journal="'+esc(f.name)+'">Download</button></li>').join(''):'<li>No saved journals yet.</li>';modal.querySelectorAll('[data-journal]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{downloadBlob(await downloadJournal(b.dataset.journal),'nerdy-learning-journal.json')}catch(e){$('#account-error').textContent=e.message}finally{b.disabled=false}});}catch(e){if($('#journals'))$('#journals').innerHTML='<li>Couldn’t load journals. Reopen this window to retry.</li>';}}
 $('#current-journal').onclick=async()=>{const button=$('#current-journal');button.disabled=true;$('#account-error').textContent='';try{const body=await exportJournal(state);downloadBlob(new Blob([body],{type:'application/json'}),'nerdy-learning-journal.json');await refreshJournals();}catch(e){$('#account-error').textContent=e.message||'Couldn’t download the journal. Please retry.'}finally{button.disabled=false}};
 await refreshJournals();
}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function setTheme(value){
 const theme=value==='dark'?'dark':'light';
 document.documentElement.dataset.theme=theme;
 document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#101e1b':'#f5f8f7';
 try{localStorage.setItem('nerdy-theme',theme)}catch{toast('Theme changed for this visit. This browser cannot save the preference.')}
}
function todayCount(){return state.attempts.filter(a=>dateKey(a.at)===dateKey()&&a.ok&&!a.hint).length}
function nav(next){page=next;render();window.scrollTo(0,0)}
function render(){if(!currentUser())return;app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">n</span><span class="word">nerdy</span><small>PLAY TO GROW</small></div><nav class="nav" aria-label="Main navigation">${[['adventure','My adventure'],['skills','Constellation'],['collection','My treasures'],['parent','For grown-ups']].map(([id,name])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="friend-note"><span class="leaf">✧</span>Little ideas.<br><strong>Brighter connections.</strong></div><button class="parent-nav" data-action="settings">${icon('gear')} Settings</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">nerdy <span class="crumb-path"> / </span><b>${{adventure:'My adventure',skills:'Constellation',collection:'My treasures',parent:'For grown-ups'}[page]}</b></div><div class="topstats"><button class="nova-header" data-action="nova" aria-label="About Nova, your AI learning spark">${novaAvatar(state,world,'small')}</button><button class="theme-toggle" data-action="theme" aria-label="${document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode'}" title="${document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode'}">${document.documentElement.dataset.theme==='dark'?'☀':'☾'}</button><div class="stat" title="Days explored — breaks never erase progress"><span>☀️</span>${state.days.length}<span class="small muted">days</span></div><button class="profile" data-nav="collection" aria-label="My treasures" title="My treasures">${state.avatar}</button></div></header>${syncStrip()}${page==='adventure'?home():page==='skills'?skillsPage():page==='collection'?collectionPage():parentPage()}<p class="footer-note">Made for curious minds. A little progress is a lovely thing.</p></main></div>`;bind();}
function home(){return homeView(state,world,week())}
function week(){const now=new Date(),monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));return `<div class="week">${['M','T','W','T','F','S','S'].map((day,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);const key=dateKey(d.getTime()),done=state.days.includes(key);return `<div class="week-day ${key===dateKey()?'today':''} ${done?'done':''}">${day}<b aria-label="${key}${done?', explored':''}">${done?'✓':key===dateKey()?'☀':'·'}</b></div>`}).join('')}</div>`}
function skillCard(s){const st=skillState(state,s.id);return `<button class="skill-card" data-start="${s.id}"><div class="skill-top"><span class="skill-symbol">${s.symbol}</span><span class="tag">${status(st)}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="bar" aria-label="${progress(st)} percent of evidence milestones"><span style="width:${progress(st)}%"></span></div></button>`}
function skillsPage(){return constellationView(state)}
const treasures=TREASURES;
function collectionPage(){const m=model(state),owned=treasures.filter(t=>treasureEarned(t)),next=treasures.find(t=>!t.crown&&!treasureEarned(t));return `<section class="greeting"><div><span class="nova-kicker">THE WONDER VAULT</span><h1>Meet your next companion.</h1><p>Every treasure has a trail. Choose one to see exactly how to earn it.</p></div><div class="day-pill">★ ${m.totalStars} / 72 stars · ${owned.length} / ${treasures.length} treasures</div></section>${next?`<section class="treasure-spotlight"><span class="treasure-halo">${next.icon}</span><div><span class="nova-kicker">NEXT ON YOUR TRAIL</span><h2>${next.name}</h2><p>Earn at least 1 star in level ${next.level}: ${NODES[next.level-1].name}.</p><button class="primary" data-node="${NODES[next.level-1].id}">Follow this treasure’s trail →</button></div></section>`:''}${WORLDS.map((w,wi)=>`<section class="treasure-world"><div class="section-title"><div><span class="nova-kicker">${w.name}</span><h2>${['Friends of the meadow','Keepers of the canopy','Wonders of the deep','A sky full of legends'][wi]}</h2></div><span>★ ${m.worlds[wi].milestones} / 18</span></div><div class="collection-grid">${treasures.filter(t=>t.world===wi).map(t=>{const st=treasureState(t,m),i=treasures.indexOf(t);return `<article class="collectible treasure-card ${st.earned?'unlocked':'locked'} ${t.crown?'crown-card':''}"><span class="treasure-tier">${t.tier}</span><button class="treasure-art" data-treasure="${i}" aria-label="Discover ${t.name}">${t.icon}<span class="treasure-spark">✦</span></button><h3>${t.name}</h3><p>${t.desc}</p><div class="treasure-requirement">${t.level===0?'Yours from the start':t.crown?'3 stars on all 6 '+w.name+' levels':'1+ stars on level '+t.level+' · '+NODES[t.level-1].name}</div><div class="bar" aria-label="${Math.min(st.current,st.target)} of ${st.target} ${t.crown?'stars':'levels'}"><span style="width:${st.target?Math.min(100,100*st.current/st.target):100}%"></span></div><button class="${st.earned?'primary':'secondary'}" ${st.earned?'data-equip="'+t.icon+'"':'data-treasure="'+i+'"'}>${st.earned?state.avatar===t.icon?'Your companion ✓':'Choose companion':t.crown?st.current+' / 18 stars · See quest':'See level '+t.level+' quest →'}</button></article>`;}).join('')}</div></section>`).join('')}<div class="info">A completed six-question level earns 1 star at 3 independent correct answers, 2 at 5, and 3 at 6. Your best stars stay forever. Replays can improve them, and every treasure shows its exact goal.</div>`;}
function treasureDialog(index){const t=treasures[index];if(!t)return;const m=model(state),st=treasureState(t,m);dialog(`<div class="treasure-reveal">${t.icon}</div><span class="nova-kicker">${t.tier}</span><h2>${t.name}</h2><p>${t.desc}</p><p>${st.earned?'Unlocked. This companion is yours to keep.':t.crown?'Earn 3 stars in each of the six '+WORLDS[t.world].name+' levels. You have '+st.current+' of 18 stars.':'Complete level '+t.level+': '+NODES[t.level-1].name+' with at least one star.'}</p><div class="dialog-actions"><button class="secondary" data-close>Back to treasures</button><button class="primary" id="treasure-go">${st.earned?'Choose companion':'Show my quest →'}</button></div>`,'treasure-dialog');$('#treasure-go').onclick=()=>{if(st.earned){state.avatar=t.icon;save();modal.close();render();}else{const target=t.crown?m.worlds[t.world].nodes.find(n=>n.stars<3):m.nodes[NODES[t.level-1].id];nodeDialog(target.id);}};}
function parentPage(){return evidenceView(state)}
function bind(){app.querySelectorAll('[data-treasure]').forEach(b=>b.onclick=()=>treasureDialog(Number(b.dataset.treasure))); app.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{world=Number(b.dataset.world);save();render()});app.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>nodeDialog(b.dataset.node));app.querySelectorAll('[data-discover]').forEach(b=>b.onclick=()=>startNode(b.dataset.discover));app.querySelectorAll('[data-landmark]').forEach(b=>b.onclick=()=>landmarkDialog(Number(b.dataset.landmark)));app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));app.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{state.grade=Number(b.dataset.grade);save();render()});app.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const t=treasures.find(t=>t.icon===b.dataset.equip);if(!treasureEarned(t))return;state.avatar=t.icon;save();render();toast('Your explorer has a new keepsake.')});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
async function action(a){
 if(a==='theme'){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');save();render();}
 if(a==='world'){world=(world+1)%4;save();render();}
 if(a==='nova')novaDialog();if(a==='insight')insightDialog();if(a==='world-story')landmarkDialog();if(a==='settings')settings();if(a==='account')await accountDialog();
 if(a==='reset'){modal.className='';modal.innerHTML='<h2>A fresh beginning?</h2><p>This resets learning progress and treasures in your account on every device. Your login and previously exported journals stay available.</p><div class="dialog-actions"><button class="secondary" id="cancel">Keep progress</button><button class="primary" id="confirm">Reset progress</button></div>';modal.showModal();$('#cancel').onclick=()=>modal.close();$('#confirm').onclick=async()=>{const button=$('#confirm');button.disabled=true;if(!await progressStore.flush()){toast(syncMessage);button.disabled=false;return;}const next=fresh();next.name=state.name;next.grade=state.grade;next.generation=crypto.randomUUID();state=next;save();if(await progressStore.flush()){modal.close();render();toast('Your new beginning is saved.')}else{toast(syncMessage);button.disabled=false;}};}
}
function settings(){modal.className='';modal.innerHTML=`<h2>Your explorer</h2><p>Make a little room for your own way to learn.</p><label for="name">Explorer name</label><input id="name" maxlength="24" value="${esc(state.name)}" autocomplete="off"><label for="grade">School grade</label><select id="grade">${[0,1,2,3,4,5].map(g=>`<option value="${g}" ${g===state.grade?'selected':''}>${g?'Grade '+g:'Kindergarten'}</option>`).join('')}</select><p class="settings-timing">Every explorer follows the same 24 levels. Questions have 30–60 seconds based on the math involved. Help or a first answer stops the clock; practice can continue.</p><label for="appearance">Appearance</label><select id="appearance"><option value="light" ${document.documentElement.dataset.theme!=='dark'?'selected':''}>Light · Sunny meadow</option><option value="dark" ${document.documentElement.dataset.theme==='dark'?'selected':''}>Dark · Moonlit meadow</option></select><label for="sound">Celebration sounds</label><select id="sound"><option value="off" ${!state.sound?'selected':''}>Off</option><option value="on" ${state.sound?'selected':''}>On</option></select><p class="small" style="margin-top:17px">Your progress and preferences are saved to your account. Only a grown-up’s email is needed.</p><div class="dialog-actions"><button class="text-button" id="manage-account">My account</button><button class="secondary" id="cancel">Cancel</button><button class="primary" id="save-settings">Save</button></div>`;modal.showModal();$('#manage-account').onclick=()=>{modal.close();void accountDialog()};$('#cancel').onclick=()=>modal.close();$('#save-settings').onclick=()=>{state.name=$('#name').value.trim()||'Explorer';state.grade=Number($('#grade').value);state.untimed=false;state.sound=$('#sound').value==='on';setTheme($('#appearance').value);save();modal.close();render()}}
function start(id){startNode(nodeForSkill(state,id))}
function startNode(node){questionClock?.stop();coachController?.abort();if(!currentUser()||!byNode[node])return;modal.close();modal.className='';const m=model(state),n=m.nodes[node];if(!n.unlocked){nodeDialog(node);return;}world=n.world;lesson={id:n.skill,node,sessionId:crypto.randomUUID(),index:0,total:6,correct:0,results:[],recall:n.due,done:false,before:m.worlds.map(w=>w.unlocked),beforeReady:m.fringe.map(n=>n.id),beforePeak:n.peak,beforeStars:n.stars,beforeTreasures:treasures.filter(t=>treasureEarned(t)).map(t=>t.name),streak:0};save();nextProblem();window.scrollTo(0,0)}
function nextProblem(){questionClock?.stop();coachController?.abort();lesson.q=novaProblem(state,lesson.node,lesson.index);lesson.started=performance.now();lesson.hinted=false;lesson.answered=false;lesson.recorded=false;lesson.retries=0;lesson.hintStep=0;lesson.reading=false;lesson.coachCache=new Map();renderLesson();window.scrollTo(0,0);questionClock=new QuestionClock(lesson.q.timeLimit,seconds=>{const el=$('#question-seconds');if(el)el.textContent=seconds;const meter=$('#question-timer');if(meter){meter.style.setProperty('--remaining',seconds/lesson.q.timeLimit);meter.classList.toggle('nearly',seconds<=8);meter.setAttribute('aria-label',seconds+' seconds remaining');}},expireQuestion,{isPaused:()=>document.hidden||modal.open||lesson?.reading});}
function stopQuestionClock(label=''){questionClock?.tick();questionClock?.stop();if(label&&$('#question-clock-label'))$('#question-clock-label').textContent=label;}
function recordFirst(ok,timedOut=false){if(lesson.recorded)return;lesson.recorded=true;const q=lesson.q;const a=recordNode(state,{node:lesson.node,ok,hint:lesson.hinted,timedOut,ms:questionClock?.elapsed||performance.now()-lesson.started,form:q.form,level:q.level,timeLimit:q.timeLimit,review:lesson.recall&&lesson.index<3,sessionId:lesson.sessionId});lesson.results.push(a);if(ok&&!lesson.hinted&&!timedOut){lesson.correct++;lesson.streak++;}else lesson.streak=0;save();}
function expireQuestion(){if(!lesson||lesson.done||lesson.recorded)return;recordFirst(false,true);lesson.hinted=true;$('#question-clock-label').textContent='Practice time';reactNova('help','Let’s work it out.','The timed try is over. You can still solve this with a clue.');showHint();}
function dots(n,gold=false){return objectGroup(n,lesson?.q.object||'seed',{group:gold?1:0})}
function visual(v){if(!v)return '';const split=(items)=>'<div class="split-model">'+items.map(x=>'<span>'+x+'</span>').join('')+'</div>';if(v.type==='count')return dots(v.a);if(v.type==='add'||v.type==='compare')return dots(v.a)+'<span class="visual-sign">'+(v.type==='add'?'+':'or')+'</span>'+dots(v.b,true);if(v.type==='subtract')return objectGroup(v.a,lesson?.q.object||'seed',{removed:v.b})+'<span class="visual-sign">− '+v.b+'</span>';if(v.type==='groups')return Array.from({length:v.a},(_,i)=>'<div class="basket-group"><small>Group '+(i+1)+'</small>'+objectGroup(v.b,lesson.q.object,{group:i})+'</div>').join('');if(v.type==='fraction')return '<div class="fraction-strip">'+Array.from({length:v.b},(_,i)=>'<span class="'+(i<v.a?'fill':'')+'"></span>').join('')+'</div>';if(v.type==='equivalent')return visual({type:'fraction',a:v.a,b:v.b})+'<span class="visual-sign">=</span>'+visual({type:'fraction',a:v.a*v.c,b:v.b*v.c});if(v.type==='fraction-add')return visual({type:'fraction',a:v.a,b:v.b})+'<span class="visual-sign">+</span>'+visual({type:'fraction',a:v.c,b:v.b});if(v.type==='shape')return '<div class="shape '+v.shape+'" role="img" aria-label="'+v.shape+'"></div>';if(v.type==='place')return '<div class="place-model">'+Array(v.a).fill('<i class="place-rod" aria-label="ten"></i>').join('')+dots(v.b)+'</div>';if(v.type==='place-labels')return split([v.a+' × 100',v.b+' × 10',v.c+' × 1']);if(v.type==='decompose')return split([Math.floor(v.a/10)*10+' + '+v.a%10,'+',Math.floor(v.b/10)*10+' + '+v.b%10]);if(v.type==='area')return '<div class="area-grid" style="--cols:'+v.a+'">'+Array(v.a*v.b).fill('<i></i>').join('')+'</div>';if(v.type==='share')return dots(v.a)+'<div class="model-baskets">'+Array(v.b).fill('<span>?</span>').join('')+'</div>';if(v.type==='ruler')return split([v.a+' cm','+',v.b+' cm']);if(v.type==='convert')return split([v.a+' × 100 cm']);if(v.type==='decimal-place')return split([v.a+' ones',v.b+' tenths']);if(v.type==='decimal-split')return split([v.a+' tenths','+',v.b+' tenths']);if(v.type==='multiply-split')return split([Math.floor(v.a/10)*10+' × '+v.b,'+',v.a%10+' × '+v.b]);return ''}

function renderLesson(){const q=lesson.q,skill=byNode[lesson.node];app.innerHTML=`<main class="session play-session world-${world}" style="--scene:url('worlds/${WORLDS[world].asset}')"><div class="session-top"><button class="close" id="exit-lesson" aria-label="Leave adventure">×</button><div class="question-progress" aria-label="Question ${lesson.index+1} of 6">${Array.from({length:6},(_,i)=>'<span class="'+(i<lesson.index?'done':i===lesson.index?'active':'')+'">'+(i<lesson.index?'✓':i+1)+'</span>').join('')}</div><span class="run-stars" title="3 correct = 1 star; 5 = 2; 6 = 3">${starMarkup(starsFor(lesson.correct))}</span></div><div class="lesson-meta"><span>LEVEL ${NODES.findIndex(n=>n.id===lesson.node)+1} · ${skill.name}</span><span>${lesson.index+1} / 6</span></div><section class="problem play-problem"><div class="problem-toolbar"><span class="question-kind">${q.form==='story'?'A little story':q.form==='visual'?'Look & discover':'Think it through'}</span><div class="question-timer" id="question-timer" style="--remaining:1" role="timer" aria-live="off"><span id="question-seconds">${q.timeLimit}</span><small id="question-clock-label">seconds</small></div></div><h1>${q.prompt}</h1>${q.display?`<div class="math-display">${q.display}</div>`:''}<div class="visual" aria-label="Visual math model">${visual(q.visual)}</div><div class="question-tools"><button class="text-button" id="read-question">${icon('sound')} Listen</button><button class="secondary" id="hint-button">✧ A little help</button></div><div id="hint-area" aria-live="polite"></div></section><div class="coach-stage" id="coach-stage"><button class="nova-character" data-action="nova" aria-label="Chat with Nova">${novaAvatar(state,world,'medium')}</button><div class="coach-bubble" aria-live="polite"><strong id="coach-title">${lesson.index===0?'Let’s do this!':'Ready for the next one?'}</strong><span id="coach-line">${lesson.index===0?'Six questions. Three stars to discover.':lesson.streak>=2?lesson.streak+' in a row. You’re on a roll!':'Look closely. You can take it one step at a time.'}</span></div><div class="celebration-particles" aria-hidden="true"></div></div><div class="answers" role="group" aria-label="Choose your answer">${q.choices.map((c,i)=>`<button class="answer" data-answer="${i}"><span class="key">${i+1}</span>${c}</button>`).join('')}</div><div class="lesson-bottom"><div class="feedback" id="feedback" aria-live="polite"></div><button class="primary" id="next-question" hidden>Next question →</button></div>${syncStrip()}<p class="footer-note">3 right = ★ · 5 right = ★★ · 6 right = ★★★<br>First answers without hints, within the question time. Your best stars are always yours.</p></main>`;
 $('#next-question').style.display='none';$('#exit-lesson').onclick=exitLesson;$('#hint-button').onclick=showHint;$('#read-question').onclick=()=>{if(!('speechSynthesis'in window)){toast('Read-aloud is not available in this browser.');return;}speechSynthesis.cancel();lesson.reading=true;const u=new SpeechSynthesisUtterance(q.prompt+' '+q.display.replaceAll('×',' times ').replaceAll('÷',' divided by ').replaceAll('−',' minus ').replaceAll('= ?',' equals what?'));u.lang='en';u.rate=.8;u.onend=u.onerror=()=>{if(lesson)lesson.reading=false;};speechSynthesis.speak(u)};
 app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));app.querySelectorAll('[data-object]').forEach(b=>b.onclick=()=>{const counted=b.getAttribute('aria-pressed')==='true';b.setAttribute('aria-pressed',String(!counted));b.classList.toggle('counted',!counted);});$('#next-question').onclick=advance;app.querySelectorAll('.cloud-status').forEach(b=>b.onclick=()=>void accountDialog());app.querySelector('[data-action="nova"]').onclick=novaDialog;
}
function reactNova(kind,title,line){const stage=$('#coach-stage');if(!stage)return;stage.className='coach-stage';void stage.offsetWidth;stage.classList.add('react-'+kind);$('#coach-title').textContent=title;$('#coach-line').textContent=line;stage.querySelector('.celebration-particles').innerHTML=kind==='great'?Array.from({length:12},(_,i)=>'<i style="--i:'+i+'">'+(i%2?'✦':'●')+'</i>').join(''):'';}
async function tutor(mode,selected,step=0){const q=lesson.q,facts=coachingFacts(q,{mode,selected,step});coachController?.abort();const controller=new AbortController();coachController=controller;const area=$('#hint-area');area.innerHTML='<div class="hint question-hint"><span class="hint-step">'+(step?'LET’S WORK IT OUT':'A CLUE FOR THIS QUESTION')+'</span><p>'+esc(facts.reply)+'</p><p class="ai-question-tip" id="ai-question-tip">Nova is thinking about this step…</p></div>';try{const context={node:q.node,index:q.index,seed:q.seed,mode,selected,step},key=JSON.stringify(context);const result=lesson.coachCache.get(key)||await askNova('coach',context,controller.signal);if(!controller.signal.aborted&&lesson?.q===q)lesson.coachCache.set(key,result);if(controller.signal.aborted||lesson?.q!==q||!$('#ai-question-tip'))return;$('#ai-question-tip').textContent=result.generated?'✦ Nova: '+result.reply:'';}catch{if(!controller.signal.aborted&&lesson?.q===q&&$('#ai-question-tip'))$('#ai-question-tip').textContent='';}}
function showHint(){if(!lesson||lesson.answered)return;lesson.hinted=true;stopQuestionClock('With a clue');const step=lesson.hintStep++%2;$('#hint-button').textContent=step?'✧ First clue again':'✧ Show me the next step';reactNova('help',step?'Let’s work it out.':'Try this little clue.',step?lesson.q.worked:lesson.q.hint);void tutor('hint',undefined,step);}
function answer(i){if(!lesson||lesson.done||lesson.answered)return;const q=lesson.q;if(!Number.isInteger(i)||i<0||i>=q.choices.length)return;const b=app.querySelector('[data-answer="'+i+'"]');if(b.disabled)return;questionClock?.tick();const ok=q.choices[i]===q.answer;stopQuestionClock(ok?'Answered':'Try again');b.classList.add(ok?'correct':'wrong');b.disabled=true;recordFirst(ok);if(!ok){lesson.retries++;lesson.hinted=true;const facts=coachingFacts(q,{mode:'wrong',selected:q.choices[i],step:lesson.retries>1?1:0});reactNova('help','Let’s check that together.',facts.observation);$('#feedback').textContent='Try another answer. Your first try is already recorded.';void tutor('wrong',q.choices[i],lesson.retries>1?1:0);return;}
 coachController?.abort();$('#hint-area').innerHTML='';lesson.answered=true;$('#hint-button').disabled=true;app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);const clean=!lesson.hinted&&!lesson.retries;reactNova('great',clean?(lesson.streak>=3?'Amazing! '+lesson.streak+' in a row!':['Awesome!','You’ve got it!','Brilliant!','Beautiful thinking!','Fantastic!','What a finish!'][lesson.index]):'You worked it out!',q.worked);$('#feedback').textContent=clean?'★ Independent answer!':'Solved with help. Try it on your own on a replay to earn more stars.';$('.run-stars').innerHTML=starMarkup(starsFor(lesson.correct));$('#next-question').hidden=false;$('#next-question').style.display='inline-flex';$('#next-question').textContent=lesson.index===5?'Reveal my stars →':'Next question →';$('#next-question').focus();if(state.sound)chime();}
function advance(){if(!lesson?.answered)return;lesson.index++;if(lesson.index>=lesson.total)finish();else nextProblem()}
function finish(){if(lesson.done)return;questionClock?.stop();coachController?.abort();lesson.done=true;if(!state.days.includes(dateKey()))state.days.push(dateKey());state.sessions.push({eventId:lesson.sessionId,id:lesson.id,node:lesson.node,at:Date.now(),correct:lesson.correct,total:lesson.total,recall:lesson.recall,scoringVersion:2});save();void progressStore.flush();const m=model(state),n=m.nodes[lesson.node],earned=starsFor(lesson.correct),next=NODES[n.order],newTreasures=treasures.filter(t=>treasureEarned(t)&&!lesson.beforeTreasures.includes(t.name));app.innerHTML=`<main class="session finish nova-finish star-finish"><div class="finish-nova">${novaAvatar(state,world,'hero',m)}<span class="finish-orbit">✦</span><span class="finish-orbit second">✧</span></div><span class="nova-kicker">LEVEL ${n.order} · ${n.name}</span><div class="star-reveal">${starMarkup(earned)}</div><h1>${earned===3?'A three-star wonder!':earned?'A new path is open!':'A little practice, a fresh try.'}</h1><p>${earned?lesson.correct+' of 6 answered independently. '+(next?'Level '+(n.order+1)+' is ready to explore.':'You’ve reached the end of all four worlds!'):'Get 3 of 6 right without hints, before time runs out, to earn your first star.'}</p><div class="finish-stats"><div><strong>${lesson.correct} / 6</strong><small>Independent answers</small></div><div><strong>${n.stars} / 3</strong><small>Your best stars</small></div><div><strong>★ ${m.totalStars}</strong><small>Across your worlds</small></div></div>${newTreasures.length?'<section class="finish-discoveries treasure-unlocks"><h2>A new companion found you!</h2>'+newTreasures.map(t=>'<button data-treasure="'+treasures.indexOf(t)+'"><span>'+t.icon+'</span><strong>'+t.name+'</strong><small>Yours to keep · tap to meet</small></button>').join('')+'</section>':''}<div class="finish-actions">${next&&m.nodes[next.id].unlocked?'<button class="primary" id="next-level">Explore level '+(n.order+1)+' →</button>':'<button class="primary" id="play-again">'+(earned?'Revisit this level':'Try again for a star')+'</button>'}${next&&m.nodes[next.id].unlocked?'<button class="secondary" id="play-again">'+(n.stars<3?'Replay for '+(n.stars+1)+' stars':'Replay this level')+'</button>':''}<button class="text-button" id="back-home">Back to my world</button></div><p class="nova-quiet">1 star: 3 right · 2 stars: 5 right · 3 stars: all 6.<br>Your best result stays. Remembering later is tracked separately.</p>${syncStrip()}</main>`;window.scrollTo(0,0);$('#back-home').onclick=()=>{lesson=null;nav('adventure')};$('#play-again').onclick=()=>startNode(lesson.node);if($('#next-level'))$('#next-level').onclick=()=>startNode(next.id);app.querySelectorAll('[data-treasure]').forEach(b=>b.onclick=()=>treasureDialog(Number(b.dataset.treasure)));app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
function exitLesson(){modal.className='';modal.innerHTML='<h2>Take a little break?</h2><p>Your answers are kept as you play. Finish all six questions to earn stars and open the next level.</p><div class="dialog-actions"><button class="secondary" id="leave">Back to my world</button><button class="primary" id="stay">Keep exploring</button></div>';modal.showModal();$('#stay').onclick=()=>modal.close();$('#leave').onclick=()=>{questionClock?.stop();coachController?.abort();modal.close();lesson=null;nav('adventure')}}
function chime(){try{const C=window.AudioContext||window.webkitAudioContext,c=new C();[523,659,784].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=f;g.gain.setValueAtTime(.035,c.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.09+.23);o.start(c.currentTime+i*.09);o.stop(c.currentTime+i*.09+.24)});setTimeout(()=>c.close(),800)}catch{}}
document.addEventListener('keydown',e=>{if(modal.open||!lesson||lesson.done)return;if(['1','2','3','4'].includes(e.key)){e.preventDefault();answer(Number(e.key)-1)}});
void boot({onReady:saved=>{state=saved;world=state.nova?.introduced?(state.world||0):3;setTheme(state.theme);render();if(!state.nova?.introduced)intro();},onSignedOut:()=>{questionClock?.stop();coachController?.abort();disposeAssistant();modal.close();state=fresh();lesson=null;page='adventure';},onStatus:updateSync,onMerge:merged=>{state=merged;if(!lesson&&currentUser())render();}});
if(document.modelContext?.registerTool){try{void Promise.resolve(document.modelContext.registerTool({name:'read_learning_summary',description:'Read the signed-in account’s learning evidence without modifying progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!currentUser())throw Error('Sign in to view learning evidence.');if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('This read-only tool takes an empty object.');return {sessions:state.sessions.length,discoveries:Object.values(model(state).nodes).map(n=>({id:n.id,stage:n.stage,recallChecks:n.checks}))}}})).catch(()=>{});}catch{}}


function treasureEarned(t){return !!t&&treasureState(t,model(state)).earned;}
function dialog(content,kind=''){disposeAssistant();disposeAssistant=()=>{};modal.close();modal.className=kind;modal.innerHTML=content;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{modal.close();modal.className=''})}
function intro(){dialog(`${novaAvatar(state,3,'hero')}<span class="nova-kicker" style="color:#e0ccff">A SPARK FROM STARLIGHT SUMMIT</span><h2>Hello. I’m Nova.</h2><p>I’m an AI learning spark. My job is to help you become a math wonder—one little discovery at a time.</p><p>My glow grows with the ideas you learn and remember. Let’s take a little of this starlight to every world.</p><div class="dialog-actions"><button class="primary" id="meet-nova">Let’s explore →</button></div><p class="nova-quiet">I help with math. For personal worries, talk with a grown-up you trust.</p>`,'nova-intro');$('#meet-nova').onclick=()=>{state.nova.introduced=true;world=0;save();modal.close();modal.className='';render()};}
function novaDialog(){disposeAssistant();modal.close();disposeAssistant=mountNovaChat(modal,{avatar:novaAvatar(state,world,'small'),request:askNova});}
function insightDialog(){disposeAssistant();modal.close();disposeAssistant=mountLearningInsight(modal,{name:state.name,request:askNova});}
function nodeDialog(id){const m=model(state),n=m.nodes[id];if(!n)return;if(!n.unlocked){const earlier=m.nodes[n.blockedBy];dialog(`<span class="nova-kicker">LEVEL ${n.order} · ${WORLDS[n.world].name}</span><h2>${n.name}</h2><p>Complete level ${earlier.order}: ${earlier.name} first.</p><p>Earn at least one star in that level: 3 of its 6 questions correct on the first try, without hints, before their timers finish.</p><div class="dialog-actions"><button class="secondary" data-close>Back to the map</button><button class="primary" id="continue-level">Go to level ${earlier.order} →</button></div>`);$('#continue-level').onclick=()=>startNode(earlier.id);return;}dialog(`${novaAvatar(state,n.world)}<span class="nova-kicker">LEVEL ${n.order} · ${WORLDS[n.world].name}</span><h2>${n.name}</h2>${starMarkup(n.stars)}<p class="node-detail-status">${n.stage} · ${n.checks} successful recall checks</p><p>Six questions. 3 correct = 1 star; 5 = 2 stars; 6 = 3 stars. One star opens the next level.</p><p>${n.ready?'Your earlier ideas make this a useful next step.':'This level is open. These earlier ideas can help:'}</p><div class="prereq-list">${n.prereqs.map(p=>'<button data-related="'+p+'">'+m.nodes[p].name+' · '+m.nodes[p].stage+'</button>').join('')||'<span class="small muted">A starting discovery—no earlier skills needed.</span>'}</div><p class="small muted">Helps you explore: ${NODES.filter(x=>x.prereqs.includes(id)).map(x=>x.name).join(', ')||'a growing collection of connected ideas'}.</p><div class="dialog-actions"><button class="secondary" data-close>Close</button><button class="primary" id="try-node">Let’s try it →</button></div>`,'nova-dialog');$('#try-node').onclick=()=>startNode(id);modal.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>nodeDialog(b.dataset.related));}
function landmarkDialog(index){const w=model(state).worlds[world];const i=index??Math.max(0,w.unlocked-1),earned=i<w.unlocked;dialog(`<span class="nova-kicker">${w.name}</span><h2>${w.landmarks[i]}</h2><p>${earned?w.story[i]:'This part of the world grows as you collect stars across its six levels.'}</p><p>${earned?'This discovery is yours to keep.':'Collect '+[1,9,18][i]+' stars in this world. You have '+w.milestones+'. Earn one star on each level to keep exploring.'}</p><div class="dialog-actions"><button class="primary" data-close>Keep exploring</button></div>`);}
